//go:build builtinassets && !embedassets
// +build builtinassets,!embedassets

package ui

import "embed"

// EmbedFS is the prometheus UI asset bundle.
//
// Upstream populates this via web/ui/embed.go, which is generated by
// scripts/compress_assets.sh after building the React/Mantine apps and
// is gitignored. promxy regenerates an equivalent embed.go at build time
// (see scripts/build_ui_assets.sh, wired into the Makefile and build.bash)
// under the `embedassets` tag, which carries the real Mantine UI bundle.
//
// This stub is the fallback for builds that set `builtinassets` but not
// `embedassets` (notably `make test`): it declares an empty embed.FS so the
// package compiles without building the UI. The mutually exclusive
// `!embedassets` constraint lets it coexist on disk with the generated
// embed.go without a duplicate EmbedFS declaration.

//go:embed README.md
var EmbedFS embed.FS
